from __future__ import annotations

from typing import Any

from models import Invoice, UserContext


def normalize(value: str) -> str:
    return value.strip().lower()


def can_read_invoice(user: UserContext, invoice: Invoice) -> bool:
    if not user.is_valid():
        return False
    if user.is_admin():
        return True
    return normalize(user.user_id) == normalize(invoice.owner_user_id)


def can_list_owner_invoices(user: UserContext, owner_user_id: str) -> bool:
    owner = normalize(owner_user_id)
    if not owner:
        return False
    if user.is_admin():
        return True
    return normalize(user.user_id) == owner


def policy_for_route(route: str) -> str:
    target = route.strip().lower()
    if target.startswith("/invoices/") and target.count("/") >= 2:
        return "invoice_read"
    if target.startswith("/invoices"):
        return "invoice_list"
    return "unknown"


def decision(
    *,
    user: UserContext,
    invoice: Invoice | None = None,
    owner_user_id: str = "",
    route: str = "",
) -> dict[str, Any]:
    policy = policy_for_route(route)
    if policy == "invoice_read":
        if invoice is None:
            return {"ok": False, "reason": "not_found"}
        if can_read_invoice(user, invoice):
            return {"ok": True, "reason": "allowed"}
        return {"ok": False, "reason": "forbidden"}
    if policy == "invoice_list":
        if can_list_owner_invoices(user, owner_user_id):
            return {"ok": True, "reason": "allowed"}
        return {"ok": False, "reason": "forbidden"}
    return {"ok": False, "reason": "unsupported"}


def redact_invoice_for_user(user: UserContext, invoice: Invoice) -> dict[str, Any]:
    data = invoice.to_dict()
    if user.is_admin() or normalize(user.user_id) == normalize(invoice.owner_user_id):
        return data
    return {
        "invoice_id": data["invoice_id"],
        "owner_user_id": "***",
        "amount_cents": 0,
        "currency": data["currency"],
        "status": "hidden",
    }


def assert_owner_or_admin(user: UserContext, owner_user_id: str) -> None:
    if not can_list_owner_invoices(user, owner_user_id):
        raise PermissionError("forbidden")


def role_capabilities(role: str) -> dict[str, bool]:
    key = normalize(role)
    return {
        "can_read_all": key == "admin",
        "can_list_all": key == "admin",
        "can_self_read": key in {"admin", "user"},
    }

