from __future__ import annotations

from typing import Any

from access_control import can_list_owner_invoices, can_read_invoice
from models import build_invoice, parse_user_context
from repository import InvoiceRepository


def _req_id(payload: dict[str, Any]) -> str:
    return str(payload.get("request_id", "")).strip() or "req-unknown"


def _invoice_id(payload: dict[str, Any]) -> str:
    return str(payload.get("invoice_id", "")).strip()


def _owner_id(payload: dict[str, Any]) -> str:
    return str(payload.get("owner_user_id", "")).strip().lower()


def get_invoice(payload: dict[str, Any], repo: InvoiceRepository) -> dict[str, Any]:
    request_id = _req_id(payload)
    user = parse_user_context(payload.get("user", {}))
    invoice_id = _invoice_id(payload)
    if not invoice_id:
        return {"ok": False, "status": 400, "reason": "missing_invoice_id", "request_id": request_id}

    invoice = repo.get(invoice_id)
    if invoice is None:
        return {"ok": False, "status": 404, "reason": "not_found", "request_id": request_id}

    # Bug: insecure direct object reference; no ownership check before return.
    return {"ok": True, "status": 200, "invoice": invoice.to_dict(), "request_id": request_id, "user": user.user_id}


def list_invoices(payload: dict[str, Any], repo: InvoiceRepository) -> dict[str, Any]:
    request_id = _req_id(payload)
    user = parse_user_context(payload.get("user", {}))
    owner_id = _owner_id(payload) or user.user_id
    if not can_list_owner_invoices(user, owner_id):
        return {"ok": False, "status": 403, "reason": "forbidden", "request_id": request_id}
    items = [invoice.to_dict() for invoice in repo.list_for_owner(owner_id)]
    return {"ok": True, "status": 200, "items": items, "request_id": request_id}


def seed_demo_data(repo: InvoiceRepository) -> None:
    rows = [
        build_invoice("inv-100", "user-a", 2500, status="open").to_dict(),
        build_invoice("inv-101", "user-b", 9900, status="paid").to_dict(),
        build_invoice("inv-102", "user-a", 1500, status="paid").to_dict(),
    ]
    repo.seed(rows)


def handle(payload: dict[str, Any], repo: InvoiceRepository) -> dict[str, Any]:
    route = str(payload.get("route", "")).strip().lower()
    if route == "get_invoice":
        return get_invoice(payload, repo)
    if route == "list_invoices":
        return list_invoices(payload, repo)
    return {"ok": False, "status": 400, "reason": "unknown_route", "request_id": _req_id(payload)}


def can_user_view_invoice(payload: dict[str, Any], repo: InvoiceRepository) -> bool:
    user = parse_user_context(payload.get("user", {}))
    invoice = repo.get(_invoice_id(payload))
    if invoice is None:
        return False
    return can_read_invoice(user, invoice)


def default_user_payload(user_id: str, email: str, role: str = "user") -> dict[str, str]:
    return {"user_id": user_id, "email": email, "role": role}


def base_request(route: str, user: dict[str, Any], request_id: str = "req-1") -> dict[str, Any]:
    return {"route": route, "user": dict(user), "request_id": request_id}


def summarize_access_attempt(payload: dict[str, Any]) -> dict[str, str]:
    user = parse_user_context(payload.get("user", {}))
    return {
        "request_id": _req_id(payload),
        "user_id": user.user_id,
        "role": user.role,
        "invoice_id": _invoice_id(payload),
        "route": str(payload.get("route", "")).strip(),
    }

