from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(slots=True)
class UserContext:
    user_id: str
    email: str
    role: str

    def normalized_user_id(self) -> str:
        return self.user_id.strip().lower()

    def normalized_role(self) -> str:
        return self.role.strip().lower()

    def is_admin(self) -> bool:
        return self.normalized_role() == "admin"

    def is_valid(self) -> bool:
        return len(self.normalized_user_id()) >= 3 and "@" in self.email


@dataclass(slots=True)
class Invoice:
    invoice_id: str
    owner_user_id: str
    amount_cents: int
    currency: str
    status: str

    def normalized_owner(self) -> str:
        return self.owner_user_id.strip().lower()

    def normalized_invoice_id(self) -> str:
        return self.invoice_id.strip()

    def is_paid(self) -> bool:
        return self.status.strip().lower() == "paid"

    def amount_dollars(self) -> float:
        return round(self.amount_cents / 100.0, 2)

    def to_dict(self) -> dict[str, Any]:
        return {
            "invoice_id": self.invoice_id,
            "owner_user_id": self.owner_user_id,
            "amount_cents": int(self.amount_cents),
            "currency": self.currency,
            "status": self.status,
        }

    @classmethod
    def from_dict(cls, raw: dict[str, Any]) -> "Invoice":
        return cls(
            invoice_id=str(raw.get("invoice_id", "")).strip(),
            owner_user_id=str(raw.get("owner_user_id", "")).strip(),
            amount_cents=int(raw.get("amount_cents", 0)),
            currency=str(raw.get("currency", "USD")).strip().upper(),
            status=str(raw.get("status", "open")).strip().lower(),
        )


def parse_user_context(raw: dict[str, Any]) -> UserContext:
    return UserContext(
        user_id=str(raw.get("user_id", "")).strip(),
        email=str(raw.get("email", "")).strip().lower(),
        role=str(raw.get("role", "user")).strip().lower(),
    )


def normalize_invoice_id(value: str) -> str:
    return value.strip()


def invoice_summary(invoice: Invoice) -> str:
    return f"{invoice.invoice_id}:{invoice.status}:{invoice.amount_cents}"


def build_invoice(
    invoice_id: str,
    owner_user_id: str,
    amount_cents: int,
    currency: str = "USD",
    status: str = "open",
) -> Invoice:
    return Invoice(
        invoice_id=invoice_id.strip(),
        owner_user_id=owner_user_id.strip().lower(),
        amount_cents=int(amount_cents),
        currency=currency.strip().upper(),
        status=status.strip().lower(),
    )

