from __future__ import annotations

from typing import Any

from models import Invoice


class InvoiceRepository:
    def __init__(self) -> None:
        self._rows: dict[str, dict[str, Any]] = {}

    def save(self, invoice: Invoice) -> None:
        self._rows[invoice.invoice_id] = invoice.to_dict()

    def get(self, invoice_id: str) -> Invoice | None:
        key = invoice_id.strip()
        if not key:
            return None
        row = self._rows.get(key)
        if row is None:
            return None
        return Invoice.from_dict(dict(row))

    def list_for_owner(self, owner_user_id: str) -> list[Invoice]:
        owner = owner_user_id.strip().lower()
        if not owner:
            return []
        result: list[Invoice] = []
        for row in self._rows.values():
            if str(row.get("owner_user_id", "")).strip().lower() == owner:
                result.append(Invoice.from_dict(dict(row)))
        return result

    def count(self) -> int:
        return len(self._rows)

    def clear(self) -> None:
        self._rows.clear()

    def seed(self, rows: list[dict[str, Any]]) -> None:
        for row in rows:
            self.save(Invoice.from_dict(row))

    def snapshot(self) -> list[dict[str, Any]]:
        return [dict(row) for row in self._rows.values()]

    def delete(self, invoice_id: str) -> bool:
        key = invoice_id.strip()
        if key in self._rows:
            del self._rows[key]
            return True
        return False

    def exists(self, invoice_id: str) -> bool:
        return self.get(invoice_id) is not None

    def owners(self) -> list[str]:
        values = {str(row.get("owner_user_id", "")).strip().lower() for row in self._rows.values()}
        return sorted([v for v in values if v])

    def by_status(self, status: str) -> list[Invoice]:
        wanted = status.strip().lower()
        if not wanted:
            return []
        return [
            Invoice.from_dict(dict(row))
            for row in self._rows.values()
            if str(row.get("status", "")).strip().lower() == wanted
        ]

    def total_amount_for_owner(self, owner_user_id: str) -> int:
        return sum(item.amount_cents for item in self.list_for_owner(owner_user_id))

    def sorted_invoice_ids(self) -> list[str]:
        return sorted(self._rows.keys())

    def stats(self) -> dict[str, int]:
        return {
            "count": self.count(),
            "paid": len(self.by_status("paid")),
            "open": len(self.by_status("open")),
        }

